import puppeteer from 'puppeteer';
import { escapeHtml } from '../engine/format';
import { ReportResult } from '../reportCenter.types';
import { reportHtml } from './reportHtml';

/**
 * Prints the template HTML with Chromium: A4 in the report's orientation, column headings
 * repeated on each page, and a footer with "generated by / on" and "Page X of Y".
 */
export async function reportPdf(r: ReportResult): Promise<Buffer> {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    timeout: 60000,
  });
  try {
    const page = await browser.newPage();
    await page.setContent(reportHtml(r), { waitUntil: 'networkidle0', timeout: 60000 });
    const footer = `<div style="font-family:Arial,sans-serif;font-size:7px;color:#666;width:100%;padding:0 9mm;display:flex;justify-content:space-between">
      <span>${escapeHtml(r.title)} · Generated by ${escapeHtml(r.generatedBy)} on ${escapeHtml(r.generatedAt)}</span>
      <span>Page <span class="pageNumber"></span> of <span class="totalPages"></span></span></div>`;
    const pdf = await page.pdf({
      format: 'A4',
      landscape: r.layout.orientation === 'landscape',
      printBackground: true,
      preferCSSPageSize: true,
      displayHeaderFooter: true,
      headerTemplate: '<span></span>',
      footerTemplate: footer,
    });
    return Buffer.from(pdf);
  } finally {
    await browser.close();
  }
}
